import datasetJson from "./generated/dataset.json"
import {
  ENERGY_TYPES,
  type Dataset,
  type EnergyType,
  type SheetId,
  type Variable,
} from "./schema"

/** Generated by scripts/convert-data.ts, which validates it against the schema. */
const dataset = datasetJson as Dataset

/** The only region in the data so far. */
export const DEFAULT_REGION = "Global"

/** One chart's worth of data: a sheet filtered to one energy type and region. */
export interface SeriesTable<S extends SheetId> {
  years: number[]
  /** Series keys are safe for use in CSS variables; names are for display. */
  series: { key: string; name: Variable<S> }[]
  /** One row per year, e.g. { year: 2010, s0: 1.2, s1: null } */
  rows: Record<string, number | null>[]
}

export function readSeries<S extends SheetId>(
  sheetId: S,
  energyType: EnergyType,
  region: string = DEFAULT_REGION
): SeriesTable<S> {
  const { years, rows: sheetRows } = dataset[sheetId]
  const selected = sheetRows.filter(
    (row) =>
      row.energyType === ENERGY_TYPES[energyType] && row.region === region
  )
  const series = selected.map((row, i) => ({
    key: `s${i}`,
    name: row.variable as Variable<S>,
  }))

  const rows = years.map((year, col) => {
    const row: Record<string, number | null> = { year }
    selected.forEach((cells, i) => {
      row[series[i].key] = cells.values[col]
    })
    return row
  })

  return { years, series, rows }
}

/** Looks up a series' key by its variable name, failing loudly if it's missing. */
export function seriesKey<S extends SheetId>(
  table: SeriesTable<S>,
  name: Variable<S>
): string {
  const series = table.series.find((s) => s.name === name)
  if (!series) throw new Error(`Series not found: ${name}`)
  return series.key
}
